const req = $('Called by Router').first().json;

const rows = $input.all()
  .map(item => item.json)
  .filter(row => Object.keys(row).length > 0);

return [{
  json: {
    data: rows,
    openaiBody: {
      model: 'gpt-4.1-mini',
      instructions:
        'You are the Sales Forecasting and Trend Analysis Agent. ' +
        'Answer only from the supplied SQL rows. If no rows were returned, ' +
        'clearly say that no matching historical data was found.',
      input:
        `Assigned task: ${req.sales_task || req.message}\n` +
        `Product subcategory: ${req.product_subcategory || 'all'}\n` +
        `SQL forecast rows: ${JSON.stringify(rows)}`,
      store: false
    }
  }
}];
